def catalogs():
    # The read descriptor uses the actual pair above. Other formal names use
    # minimal unchanged schemas to isolate registration/mutation assertions.
    tools = [{"name": name, "description": "descriptor " + name,
              "inputSchema": {"type": "object", "properties": {}, "additionalProperties": False}}
             for name in sorted(FULL)]
    next(t for t in tools if t["name"] == "read")["inputSchema"] = copy.deepcopy(ACTUAL_MCP_READ)
    declarations = [{"name": t["name"], "description": t["description"], "strict": False,
                     "type": "function", "parameters": copy.deepcopy(
                         ACTUAL_RESPONSE_READ if t["name"] == "read" else t["inputSchema"])}
                    for t in tools]
    body = {"tools": [], "input": [{"type": "additional_tools", "role": "developer",
            "tools": [{"type": "namespace", "name": "mcp__huyang", "tools": declarations}]}]}
    return tools, body

def read_declaration(body):
    return next(t for t in body["input"][0]["tools"][0]["tools"] if t["name"] == "read")


class CodexSchemaTests(unittest.TestCase):
    def test_actual_read_pair_and_loss_paths_without_mutating_raw_catalogs(self):
        original = copy.deepcopy(ACTUAL_MCP_READ)
        projected, lost = codex_schema(ACTUAL_MCP_READ)
        self.assertEqual(projected, ACTUAL_RESPONSE_READ)
        self.assertEqual(ACTUAL_MCP_READ, original)
        self.assertEqual({item["path"] for item in lost}, {
            "/$schema", "/properties/end_line/minimum", "/properties/limit/minimum",
            "/properties/max_lines/minimum", "/properties/start_line/minimum",
            "/properties/targets/maxItems", "/properties/targets/items/properties/end_line/minimum",
            "/properties/targets/items/properties/max_lines/minimum",
            "/properties/targets/items/properties/start_line/minimum"})
        self.assertEqual(next(item["value"] for item in lost
                              if item["path"] == "/properties/targets/maxItems"), 32)
        tools, body = catalogs()
        before = copy.deepcopy((tools, body))
        evidence = check_codex_catalog(tool_catalog(body), tools)
        self.assertEqual(set(evidence), FULL)
        self.assertEqual(evidence["read"]["dropped"], lost)
        self.assertEqual((tools, body), before)

    def test_other_observed_losses_and_schema_positions_only(self):
        # Actual search/change_plan leaf limits, plus keywords used as property
        # names and enum data: those are NOT schema positions to strip.
        source = {"type": "object", "properties": {
            "limit": {"type": "integer", "minimum": 1, "maximum": 200},
            "content": {"type": "string", "maxLength": 4194304},
            "minimum": {"type": "string", "enum": [{"maxItems": 9}]}}}
        projected, lost = codex_schema(source)
        self.assertEqual(projected, {"type": "object", "properties": {
            "limit": {"type": "integer"}, "content": {"type": "string"},
            "minimum": {"type": "string", "enum": [{"maxItems": 9}]}}})
        self.assertEqual({item["path"] for item in lost},
                         {"/properties/limit/minimum", "/properties/limit/maximum",
                          "/properties/content/maxLength"})

    def test_pinned_type_defaults_and_composition_early_return(self):
        source = {"type": ["object", "null"], "oneOf": [{"type": "array"}]}
        self.assertEqual(codex_schema(source)[0], {
            "type": ["object", "null"], "properties": {},
            "oneOf": [{"type": "array", "items": {"type": "string"}}]})
        self.assertEqual(codex_schema({"oneOf": [{"type": "string"}]})[0],
                         {"oneOf": [{"type": "string"}]})
        self.assertEqual(codex_schema({"minimum": 1})[0], {"type": "number"})

    def test_model_mutations_fail_including_compaction(self):
        mutations = {
            "drop minItems": lambda s: s["properties"]["targets"].pop("minItems"),
            "drop property": lambda s: s["properties"].pop("root"),
            "drop description": lambda s: s["properties"]["max_lines"].pop("description"),
            "change description": lambda s: s["properties"]["max_lines"].update(description="shortened"),
            "required": lambda s: s["properties"]["target"]["oneOf"][0].update(required=[]),
            "enum": lambda s: s["properties"]["view"].update(enum=["source"]),
            "additionalProperties": lambda s: s.update(additionalProperties=True),
            "branch": lambda s: s["properties"]["target"]["oneOf"].pop(),
            "missing object default": lambda s: s["properties"]["target"].pop("properties"),
            "unexpected constraint": lambda s: s["properties"]["end_line"].update(minimum=1),
            "compaction": lambda s: (s.clear(), s.update(type="object", properties={})),
            "bool versus number": lambda s: s.update(additionalProperties=0),
        }
        for label, mutate in mutations.items():
            with self.subTest(label=label):
                tools, body = catalogs()
                mutate(read_declaration(body)["parameters"])
                with self.assertRaisesRegex(AssertionError, "model schema differs"):
                    check_codex_catalog(tool_catalog(body), tools)

    def test_unapproved_source_losses_fail_closed(self):
        for extra in ({"title": "new metadata"}, {"pattern": "x"},
                      {"const": "x"}, {"$ref": "#/$defs/T"}, {"$defs": {}},
                      {"definitions": {}}, {"description": None}):
            with self.subTest(extra=extra):
                tools, body = catalogs()
                next(t for t in tools if t["name"] == "read")["inputSchema"].update(extra)
                with self.assertRaises(AssertionError):
                    check_codex_catalog(tool_catalog(body), tools)
        for schema in (True, False, {"description": "would be cleared"}, {"type": "null"}):
            with self.subTest(schema=schema), self.assertRaises(AssertionError):
                codex_schema(schema)

    def test_registration_names_strict_and_descriptions_fail_closed(self):
        mutations = {
            "strict true": lambda t: t.update(strict=True),
            "strict missing": lambda t: t.pop("strict"),
            "strict zero": lambda t: t.update(strict=0),
            "description": lambda t: t.update(description="compacted"),
            "description missing": lambda t: t.pop("description"),
            "name": lambda t: t.update(name="unexpected_read"),
            "type": lambda t: t.update(type="custom"),
        }
        for label, mutate in mutations.items():
            with self.subTest(label=label):
                tools, body = catalogs()
                mutate(read_declaration(body))
                with self.assertRaises(AssertionError):
                    check_codex_catalog(tool_catalog(body), tools)
        for mode in ("missing", "extra", "duplicate", "namespace"):
            with self.subTest(mode=mode):
                tools, body = catalogs()
                namespace = body["input"][0]["tools"][0]
                if mode == "missing":
                    namespace["tools"].pop()
                elif mode == "extra":
                    namespace["tools"].append({**copy.deepcopy(read_declaration(body)), "name": "unknown"})
                elif mode == "duplicate":
                    namespace["tools"].append(copy.deepcopy(read_declaration(body)))
                else:
                    namespace["name"] = "other_huyang"
                with self.assertRaises(AssertionError):
                    check_codex_catalog(tool_catalog(body), tools)


class MemoryLog:
    """Exercise the real record encoder/append contract without filesystem writes."""
    def __init__(self):
        self.paths = {}
        self.entries = []

    def open(self, path, flags, mode):
        fd = len(self.paths) + 100
        self.paths[fd] = str(path)
        return fd

    def write(self, fd, data):
        self.entries.append((self.paths[fd], json.loads(data)))
        return len(data)

    def patches(self):
        from contextlib import ExitStack
        stack = ExitStack()
        stack.enter_context(patch.object(common.os, "open", self.open))
        stack.enter_context(patch.object(common.os, "write", self.write))
        stack.enter_context(patch.object(common.os, "close"))
        return stack


class MemoryWriter:
    def __init__(self):
        self.data = bytearray()
        self.closed = False

    def write(self, data):
        self.data.extend(data)

    async def drain(self):
        pass

    def close(self):
        self.closed = True


class DiscoveryRelayTests(unittest.IsolatedAsyncioTestCase):
    def test_record_keeps_route_path_separate_from_destination(self):
        log = MemoryLog()
        entry = {"path": "/ollama/api/tags", "providerID": "ollama"}
        with log.patches():
            record(Path("/synthetic/model-http.jsonl"), **entry)
        destination, saved = log.entries[0]
        self.assertEqual(destination, "/synthetic/model-http.jsonl")
        self.assertEqual(saved["path"], entry["path"])
        self.assertEqual(saved["providerID"], "ollama")
        self.assertIn("time_ns", saved)
        self.assertIn("pid", saved)

    async def test_actual_http_discovery_branch_preserves_route_and_never_advances_workflow(self):
        routes = {"/ollama/api/tags": ("ollama", {"models": []}),
                  "/lmstudio/api/v1/models": ("lmstudio", {"models": []}),
                  "/vllm/health": ("vllm", {}),
                  "/vllm/v1/models": ("vllm", {"data": []})}
        for route, (provider, response) in routes.items():
            with self.subTest(route=route):
                owner = Controller("/synthetic/case", {})
                reader, writer = asyncio.StreamReader(), MemoryWriter()
                reader.feed_data(("GET " + route + " HTTP/1.1\r\nHost: 127.0.0.1\r\n\r\n").encode())
                reader.feed_eof()
                log = MemoryLog()
                with log.patches():
                    await owner.http_request(reader, writer)
                head, payload = bytes(writer.data).split(b"\r\n\r\n", 1)
                self.assertTrue(head.startswith(b"HTTP/1.1 200 "), head)
                self.assertEqual(json.loads(payload), response)
                self.assertTrue(writer.closed)
                self.assertEqual(owner.failures, [])
                self.assertEqual(owner.count, 0)
                self.assertEqual(owner.workflows, {})
                self.assertEqual(owner.schemas, {})
                self.assertEqual(owner.http_catalogs[0]["tools"], [])
                self.assertEqual(owner.http_catalogs[0]["additional_tools"], [])
                entry, = owner.discovery
                self.assertEqual(entry, {"auxiliary": "provider-discovery", "providerID": provider,
                                         "method": "GET", "path": route, "response": response})
                saved, = [value for path, value in log.entries
                          if value.get("auxiliary") == "provider-discovery" and "path" in value]
                self.assertEqual(saved["path"], route)
                self.assertEqual(saved["providerID"], provider)
                self.assertIn(("/synthetic/case/model-http.jsonl", saved), log.entries)


class WorkflowSchemaTests(unittest.IsolatedAsyncioTestCase):
    def workflow(self, tools):
        owner = SimpleNamespace(case=Path("/synthetic/case"), catalogs={"full": tools},
                                schemas={("full", t["name"]): t["inputSchema"] for t in tools})
        with patch("workflow.snapshot", return_value={"sha256": "synthetic"}):
            return Workflow(owner, "schema-probe", "/synthetic/case/fixture", probe=True)

    async def test_actual_pair_passes_responses_workflow_and_retains_raw_model_schema(self):
        tools, body = catalogs()
        wf = self.workflow(tools)
        log = MemoryLog()
        with log.patches():
            call = await wf.advance(body, "responses")
        self.assertEqual(call["base"], "read")
        self.assertEqual(call["namespace"], "mcp__huyang")
        self.assertEqual(wf.catalogs[0]["tools"]["read"]["schema"], ACTUAL_RESPONSE_READ)
        projection, = [v["codex_schema_projection"] for _, v in log.entries if "codex_schema_projection" in v]
        self.assertEqual(set(projection), FULL)
        self.assertTrue(projection["read"]["dropped"])

    async def test_workflow_rejects_responses_constraint_loss(self):
        tools, body = catalogs()
        read_declaration(body)["parameters"]["properties"]["targets"].pop("minItems")
        wf = self.workflow(tools)
        with MemoryLog().patches(), self.assertRaisesRegex(AssertionError, "model schema differs"):
            await wf.advance(body, "responses")

    async def test_claude_keeps_existing_unprojected_comparison(self):
        tools, _ = catalogs()
        body = {"tools": [{"name": "mcp__huyang__" + t["name"], "description": t["description"],
                           "input_schema": copy.deepcopy(t["inputSchema"])} for t in tools]}
        wf = self.workflow(tools)
        with MemoryLog().patches():
            call = await wf.advance(body, "anthropic")
        self.assertEqual(call["base"], "read")
        next(t for t in body["tools"] if t["name"] == "mcp__huyang__read")["input_schema"] = ACTUAL_RESPONSE_READ
        wf = self.workflow(tools)
        with MemoryLog().patches(), self.assertRaisesRegex(AssertionError, "model schema differs"):
            await wf.advance(body, "anthropic")


